class Graph:
    def __init__(self,lanes):self.nodes={};self.edges=[];self.lanes=lanes
    def node(self,i,lane,label,shape='action'):self.nodes[i]=(lane,label,shape);return i
    def edge(self,a,b,label=''):self.edges.append((a,b,label))
    def code(self):
        out='flowchart TB\n'
        for lane in self.lanes:
            out+='  subgraph lane'+lane+'["'+PEOPLE[lane][0]+'"]\n'
            for i,(l,label,shape) in self.nodes.items():
                if l!=lane:continue
                escaped=label.replace('&','&amp;').replace('"','&quot;') or '#160;';syntax={'action':'(["'+escaped+'"])','decision':'{"'+escaped+'"}','start':'(("Start"))','end':'((("End")))','bar':'@{ shape: fork }'}[shape]
                out+='    '+i+syntax+'\n'
            out+='  end\n'
        for a,b,label in self.edges:out+='  '+a+(' -->|"'+label+'"| ' if label else ' --> ')+b+'\n'
        bars=[i for i,v in self.nodes.items() if v[2]=='bar']
        if bars:out+='  classDef bar fill:#333,stroke:#333,color:#333;\n  class '+','.join(bars)+' bar;\n'
        return out

