    for i,l,label,shape in [('start','RE','', 'start'),('capture','RE',capture,'action'),('forkRE','RE','Source control bar','bar'),('delegateRE','RE','Delegation Agreement','decision'),('responseRE','RE','Receive and Process Response','action'),('acceptedRE','RE','', 'decision'),('correctRE','RE','Corrective Action','action'),('endRE','RE','', 'end'),('receiveCA','CA','Receive Message (a)','action'),('delegateCA','CA','Delegation Agreement','decision'),('processCA','CA','Process Message','action'),('forkCA','CA','Source control bar','bar'),('submitCA','CA','Submit Message','action'),('waitCA','CA','Source control bar','bar'),('responseCA','CA','Receive Response','action'),('delegateResponse','CA','Delegation Agreement','decision'),('processResponse','CA','Process Response','action'),('acceptedCA','CA','','decision'),('routeCA','CA','Route Response','action'),('mergeCA','CA','Source control bar','bar'),('endCA','CA','','end'),('mergeSA','SA','Source control bar','bar'),('receiveSA','SA','Receive Message (b)','action'),('processSA','SA','Process Message and Generate Status Advice','action'),('delegateSA','SA','Delegation Agreement','decision')]:n(i,l,label,shape)
    for a,b,label in [('start','capture',''),('capture','forkRE',''),('forkRE','delegateRE',''),('forkRE','responseRE',''),('delegateRE','mergeSA','Data Collection Agreement'),('delegateRE','receiveCA','No Data Collection Agreement'),('receiveCA','delegateCA',''),('delegateCA','submitCA','Calculation Agreement'),('delegateCA','processCA','No Calculation Agreement'),('processCA','forkCA',''),('forkCA','submitCA',''),('forkCA','mergeCA',''),('submitCA','waitCA',''),('waitCA','mergeSA',''),('waitCA','responseCA',''),('mergeSA','receiveSA',''),('receiveSA','processSA',''),('processSA','delegateSA',''),('delegateSA','responseCA','No Data Collection Agreement'),('delegateSA','mergeCA','Data Collection Agreement'),('responseCA','delegateResponse',''),('delegateResponse','routeCA','Calculation Agreement'),('delegateResponse','processResponse','No Calculation Agreement'),('processResponse','acceptedCA',''),('acceptedCA','endCA','Accepted'),('acceptedCA','routeCA','Rejected'),('routeCA','mergeCA',''),('mergeCA','responseRE',''),('responseRE','acceptedRE',''),('acceptedRE','endRE','Accepted'),('acceptedRE','correctRE','Rejected'),('correctRE','capture','')]:e(a,b,label)
    return g

