        for a,b,label in [('start','calculate',''),('calculate','fork',''),('fork','receive',''),('fork','response',''),('receive','process',''),('process','response',''),('response','decision',''),('decision','endCA','Accepted'),('decision','correct','Rejected'),('correct','calculate','')]:e(a,b,label)
