def usecase(num):
    code='usecase-beta\ndirection TB\n';actors={};cases={};edges=[];notes=[]
    if num==1:
        actors={'SA':('Supervisory Authority','supervisory-authority'),'CA':('Competent Authority','competent-authority'),'RM':('RMs','rm'),'SI':('SIs','si'),'MTF':('MTF','mtf'),'OTF':('OTFs','otf'),'APA':('APAs','apa'),'CTP':('CTPs','ctp'),'IF':('IF','if'),'ARM':('ARM','arm')}
        for p in ['RM','SI','MTF','OTF','APA','CTP']:
            edges.extend([(p,'SA','--|>'),(p,'CA','--|>')])
        edges.extend([('CA','SA','--|>'),('IF','CA','--|>'),('ARM','CA','--|>')])
        notes=['This is a literal reconstruction of the source hollow-triangle actor connectors. Native use-case syntax renders them as generalization glyphs. The diagram is not treated as proof that a trading venue or firm is a subtype of a regulatory authority: T10–T12 distinguish functional participants and business roles. The source notation versus role semantics remains unresolved (issue-000035). No institutional equivalence is asserted.']
    elif num==2:
        actors={'CA':('Competent Authority','competent-authority'),'SA':('Supervisory Authority','supervisory-authority'),'RE':('Reporting Entity','reporting-entity')}
        cases={'ref':'Reference Data','submission':'Reference Data Submission','dates':'Non-Working Day Submission','distribution':'Reference Data Distribution','transparency':'Transparency Data','volume':'Trading Volume Cap','transreport':'Transparency Data Report Submission','activity':'Trading Activity Report Submission','result':'Trading Activity Result Submission','equity':'Equity','nonequity':'Non-Equity'}
        edges=[('CA','SA','--'),('SA','RE','--'),('SA','ref','--'),('SA','transparency','--'),('SA','volume','--'),('ref','submission','--'),('ref','dates','--'),('ref','distribution','--'),('transparency','transreport','--'),('transparency','activity','--'),('transparency','result','--')]+[(a,b,'--') for a in ['transreport','activity','result'] for b in ['equity','nonequity']]
        notes=['All visible connectors in this picture are plain undirected associations. Crossings with bridge humps are not junctions. Equity and Non-Equity connect separately to each of the three transparency-related submissions; no include, extend or generalization is added.']
    else:
        actors={'RE':('Reporting Entity','reporting-entity'),'CA1':('Competent Authority','competent-authority'),'CA2':('Competent Authority','competent-authority')};cases={'submit':'Transaction Data Submission','exchange':'Transaction Data Exchange'};edges=[('RE','CA1','--'),('CA1','CA2','--'),('RE','submit','--'),('CA1','exchange','--'),('CA2','exchange','--')]
        notes=['Two distinct Competent Authority actor occurrences are preserved. They represent the two parties to exchange in this picture; a repeated functional role is not deduplicated into one actor. All connectors are undirected as drawn.']
    for i,(label,slug) in actors.items():code+='actor '+i+'("'+label+'")\n'
    for i,label in cases.items():code+=i+'("'+label+'")\n'
    for a,b,connector in edges:code+=a+' '+connector+' '+b+'\n'
    return code,actors,cases,edges,notes

def main(root):
    src=next(s for s in kb.sources(root) if s['source_id']==SID);base=root/src['set_path'];out=base/'diagrams/fitrr-activities';d=json.loads((root/'work/documents'/SID/'records.json').read_text(encoding='utf-8'));tables={int(t['source_table_id'][1:]):t for t in d['tables']};inv=json.loads((root/'work/documents'/SID/'media-review-inventory.json').read_text(encoding='utf-8'));media={int(o['figure_id'][4:]):(m,o) for m in inv['media'] for o in m['occurrences']};outputs=[]
    def participant(slug):return root/'shared/reference/participants'/f'participant-{SID}-{slug}.md'
    for num in [1,2,3]+list(range(8,17)):
        page=out/f'fig-{num:04d}.md';item,occ=media[num];flow=None;notes=[];flowids=[]
        if num<=3:
            code,actors,cases,edges,notes=usecase(num);title={1:'Business roles and functional participants — source notation',2:'Financial instrument reporting use cases',3:'Transaction data submission and exchange use cases'}[num];kind='usecase-beta';pids=sorted({'participant-'+SID+'-'+v[1] for v in actors.values()});body='## Actors and relationships\n\n'+kb.table(['Actor occurrence','Source label','Canonical scoped role'],[[i,label,kb.link(page,participant(slug),label)] for i,(label,slug) in actors.items()]);labels={**{i:v[0] for i,v in actors.items()},**cases};body+=kb.table(['From / endpoint 1','To / endpoint 2','Source connector'],[[labels[a],labels[b],'Hollow triangle toward endpoint 2' if c=='--|>' else 'Plain undirected association'] for a,b,c in edges]);body+='\nNo system boundary is drawn in the source, so none is invented.\n';status='needs-review'
        else:
            heading,tn,condition_tn,title,sequences=DETAIL[num];g=activity(num);code=g.code();kind='flowchart';pids=sorted({'participant-'+SID+'-'+PEOPLE[l][1] for l in g.lanes});flow=next((base/'flows').glob(f'flow-{SID}-p{heading}-*.md'));fm,fb=kb.metadata(flow);flowids=[fm['flow_id']];body='## Activities, actors and control paths\n\n'+kb.table(['Node','Responsible source lane','Literal source label','Source shape'],[[i,PEOPLE[l][0],label or ('Unlabelled decision' if shape=='decision' else shape),shape] for i,(l,label,shape) in g.nodes.items()])+kb.table(['From','To','Source path condition'],[[a,b,label or 'Unlabelled'] for a,b,label in g.edges]);notes=['Mermaid flowchart subgraphs preserve the source swimlanes. Dark bar nodes retain each source control bar and all connected edges; they are not silently flattened into exclusive decisions. Source start/final symbols become labelled circles; blank source decisions remain unlabelled.','Node IDs in the edge table distinguish otherwise repeated labels. The source original is retained for exact geometry; no additional business path or timing is inferred.']
            if num==9:notes+=['The Reporting Entity lane is empty in this activity picture. Narrative P199 and sequence figure23 additionally include Public, Reporting Entity and 3rd Party Systems; this activity diagram intentionally presents only the CA distribution-processing path.']
            if num==11:notes+=['T26 Receive Message row prints initiator SA, but its description says CA and this activity is in the Competent Authority lane. Both claims are retained (issue-000036).']
            if num==14:notes+=['The Reporting Entity lane is empty. T18 Role names SA while this picture, T29 and P233–P235 assign calculation/submission to CA; issue-000032.']
            if num==16:notes+=['The activity picture ends after the Relevant Competent Authority generates status; it does not draw a return arrow. Sequence figure36 separately shows that response. The source label Transactions Report Message is preserved, though T31 uses Transaction Report Message.']
            body+='\n## Responsibilities from the activity table\n\n'+kb.link(page,base/f'documents/{SID}/tables/tbl-{tn:04d}.md','T'+str(tn))+' preserves every action description and source Initiator value.\n'
            fm.update(document_kind='business-flow',manual_curated=True,title=title,participants=pids,participant_ids=pids,related_diagrams=[page.relative_to(root).as_posix()],limitations=notes)
            fbody='# '+title+'\n\n'+kb.source_link(root,flow,src)+'; '+' / '.join(occ['heading_path'])+'; '+occ['source_locator']+'; T'+str(tn)+'.\n\n## Purpose and source conditions\n\n'
            for ctn in ([20,21] if num==16 else [condition_tn] if condition_tn else []):fbody+=kb.link(flow,base/f'documents/{SID}/tables/tbl-{ctn:04d}.md','T'+str(ctn))+'\n\n'+kb.table(tables[ctn]['rows'][0],tables[ctn]['rows'][1:])+'\n'
            if num==11:fbody+='The SA checks for missing venue submissions and incomplete expected data. It generates venue-specific status advice to trigger correction (T26 rows2–3, P202).\n\n'
            fbody+='## Participants and their responsibilities\n\n'+'\n'.join('- '+kb.link(flow,participant(PEOPLE[l][1]),PEOPLE[l][0]) for l in g.lanes)+'\n\n'+kb.table(tables[tn]['rows'][0],tables[tn]['rows'][1:])+'\n## Decisions, ordered paths and exceptional outcomes\n\n'+kb.link(flow,page,'Full activity reconstruction and labelled edge table')+'\n\nEach table row describes an activity, not a universal linear execution order. Follow the graph for delegation choices, fork/merge paths, accepted outcomes and corrective-action loops.\n\n## Message exchanges and related flows\n\n'
            for seq in sequences:fbody+='- '+kb.link(flow,base/f'diagrams/fitrr-sequences/fig-{seq:04d}.md','Sequence '+str(seq)+' with sender/receiver, message families and narrative')+'\n'
            if num==9:fbody+='\nAdditional narrative participants: '+kb.link(flow,participant('public'),'Public')+' and '+kb.link(flow,participant('third-party-systems'),'3rd Party Systems')+'. These roles are absent from this activity swimlane picture but present in P199/figure23.\n'
            fbody+='\n## Limitations\n\n'+'\n'.join('- '+x for x in notes)+'\n';kb.put(flow,kb.front(fm)+fbody);status='needs-review'
        meta={'template':False,'document_kind':'diagram','review_status':status,'manual_curated':True,'diagram_id':f'fig-{num:04d}','title':title,'domain':'securities','source_ids':[SID],'source_editions':['July 2025'],'message_sets':['fitrr'],'participant_ids':pids,'flow_ids':flowids,'content_origin':'source-reconstruction','diagram_kind':kind,'original_asset':item['original'],'source_locations':[{'source_id':SID,'locator':occ['source_locator'],'heading_path':occ['heading_path'],'xml_path':occ['xml_path'],'figure_id':occ['figure_id']}],'render_status':'not-run','visual_review':'not-run','limitations':notes,'updated':DATE}
        kb.put(page,kb.front(meta)+'# '+title+'\n\n'+kb.source_link(root,page,src)+'; '+occ['source_locator']+'; '+' / '.join(occ['heading_path'])+'.\n\n'+kb.link(page,root/item['original'],'Original source figure')+' · '+kb.link(page,root/item['preview'],'Readable original preview')+(' · '+kb.link(page,flow,'Reusable business flow') if flow else '')+'\n\n## Source reconstruction\n\n```mermaid\n'+code+'```\n\n'+body+'\n## Qualifications\n\n'+'\n'.join('- '+x for x in notes)+'\n\n## Rendering and visual review\n\nPending parse/render and explicit comparison with the original.\n');kb.put(page.with_suffix('.mmd'),code)
        ep=root/occ['evidence_page'];em,eb=kb.metadata(ep);em.update(canonical_diagram=page.relative_to(root).as_posix(),disposition='canonical-reconstruction-created-needs-review');eb=re.sub(r'\n<!-- FITRR-ACTIVITY -->.*','',eb,flags=re.S);kb.put(ep,kb.front(em)+eb.strip()+'\n\n<!-- FITRR-ACTIVITY -->\n'+kb.link(ep,page,'Canonical source reconstruction and review evidence')+'\n')
        for pid in pids:
            pp=root/'shared/reference/participants'/(pid+'.md');pm,pb=kb.metadata(pp);tag='FITRR-ACTIVITY-'+str(num);pb=re.sub(r'\n<!-- '+tag+' -->.*?<!-- /'+tag+' -->\n?','\n',pb,flags=re.S);pb+='\n<!-- '+tag+' -->\n'+kb.link(pp,page,title)+(' · '+kb.link(pp,flow,'Activities and responsibilities') if flow else '')+'\n<!-- /'+tag+' -->\n';pm['flow_ids']=sorted(set(pm.get('flow_ids',[])+flowids));kb.put(pp,kb.front(pm)+pb.strip()+'\n')
        outputs.append({'figure_id':f'fig-{num:04d}','path':page.relative_to(root).as_posix(),'original':item['original'],'original_sha256':item['original_sha256'],'source_preview':item['preview'],'mermaid_sha256':hashlib.sha256(page.with_suffix('.mmd').read_bytes()).hexdigest(),'flow_path':flow.relative_to(root).as_posix() if flow else None,'limitations':notes})
    index=out/'index.md';kb.put(index,kb.front({'template':False,'document_kind':'diagram-index','review_status':'needs-review','source_ids':[SID],'source_editions':['July 2025'],'domain':'securities','message_sets':['fitrr']})+'# FITRR use cases and activities\n\n'+kb.table(['Figure','Source reconstruction','Flow'],[[x['figure_id'],kb.link(index,root/x['path'],x['figure_id']),kb.link(index,root/x['flow_path'],'Responsibilities') if x['flow_path'] else 'Source overview'] for x in outputs]))
    for nav in [base/'index.md',base/'participants.md',base/'flows/index.md']:
        m,b=kb.metadata(nav);b=re.sub(r'\n<!-- FITRR-ACTIVITY-INDEX -->.*','',b,flags=re.S);kb.put(nav,kb.front(m)+b.strip()+'\n\n<!-- FITRR-ACTIVITY-INDEX -->\n'+kb.link(nav,index,'FITRR use cases, activity flows and participant responsibilities')+'\n')
    kb.dump(root/'work/fitrr-activities.json',{'source_id':SID,'source_sha256':src['sha256'],'outputs':outputs});print(json.dumps({'diagrams':len(outputs),'activities':len(DETAIL)}))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);a=p.parse_args();main(a.root.resolve())
